-- Insertar RouteStop links para la ruta SENA
INSERT INTO Route.RouteStop (Id, RouteId, StopId, OrderSequence, Status)
SELECT v.Id, v.RouteId, v.StopId, v.OrderSequence, 'Active'
FROM (VALUES
    ('F7000211-0000-4000-8000-000000000211', 'F1000023-0000-4000-8000-000000000023', 'F2000031-0000-4000-8000-000000000031', 1),
    ('F7000212-0000-4000-8000-000000000212', 'F1000023-0000-4000-8000-000000000023', 'F2000032-0000-4000-8000-000000000032', 2),
    ('F7000213-0000-4000-8000-000000000213', 'F1000023-0000-4000-8000-000000000023', 'F2000033-0000-4000-8000-000000000033', 3),
    ('F7000214-0000-4000-8000-000000000214', 'F1000023-0000-4000-8000-000000000023', 'F2000034-0000-4000-8000-000000000034', 4),
    ('F7000215-0000-4000-8000-000000000215', 'F1000023-0000-4000-8000-000000000023', 'F2000035-0000-4000-8000-000000000035', 5),
    ('F7000216-0000-4000-8000-000000000216', 'F1000023-0000-4000-8000-000000000023', 'F2000036-0000-4000-8000-000000000036', 6)
) AS v (Id, RouteId, StopId, OrderSequence)
WHERE NOT EXISTS (SELECT 1 FROM Route.RouteStop rst WHERE rst.RouteId = v.RouteId AND rst.StopId = v.StopId);